contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 time) public payable {
        require(address(this).balance >= amount, "insufficient balance");
        require(time > block.timestamp, "time must be in the future");

        bool reverted;

        // First call: use a small amount to setup a known pastBlockTime
        if (amount == 10 ether) {
            // Need to call with 10 ether and time > pastBlockTime to set pastBlockTime
            (bool success1, ) = address(c).call{value: amount}("");
            require(success1, "setup call failed");

            // Now c.pastBlockTime() == time (since time > block.timestamp and previous pastBlockTime was 0 or less)
            // Second call: same amount and same time should revert because block.timestamp > pastBlockTime is false (time > pastBlockTime?) 
            // Actually second call would have block.timestamp == time? No, block.timestamp is current block timestamp, which is < time because we required time > block.timestamp.
            // The condition uses block.timestamp, not the time parameter. So we cannot control block.timestamp.
            // The setup is not meaningful because time is not used in the call; block.timestamp is the actual timestamp.
            // We must drive the fallback with actual msg.value and actual block.timestamp.
        }

        // To test the revert condition on amount and block.timestamp order, we cannot control block.timestamp.
        // So we can only test that when amount != 10 ether, it reverts; and when amount == 10 ether, the result depends on block.timestamp > pastBlockTime.
        // But pastBlockTime might be 0 initially (deployed fresh). So first call with amount == 10 ether will succeed because block.timestamp > 0.
        // Second call in same transaction? We cannot make two calls and change block.timestamp; block.timestamp is constant within a transaction.
        // So if we call twice with 10 ether in the same transaction, second call will revert because block.timestamp == pastBlockTime (same block).

        // Let's design: we do one call with amount. If amount != 10 ether, it must revert.
        // If amount == 10 ether, it must succeed if block.timestamp > pastBlockTime (initially true), but we cannot guarantee a second call.

        // Prepare: we need to observe the outcome of a single call with given amount.
        // We already have the setup call? Let's do only one deciding call.

        // For general rule: the fallback reverts if msg.value != 10 ether. If msg.value == 10 ether and block.timestamp > pastBlockTime, it succeeds.
        // Since pastBlockTime is initially 0 (fresh contract), first call with 10 ether succeeds.
        // But we must account for possible prior calls in this test? The checker runs run() once on a fresh c.
        // So c is fresh, pastBlockTime == 0.

        // So we can test: if amount != 10 ether -> revert; if amount == 10 ether -> success.

        // But we need to make the call and capture revert.

        // But wait: the fallback also transfers balance if block.number % 15 == 0. That does not affect revert.

        // So deciding call:
        bool success;
        (success, ) = address(c).call{value: amount}("");

        // Now assert general rule:
        // success == (amount == 10 ether)
        assert(success == (amount == 10 ether));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 wrongAmount) public payable {
        require(address(this).balance >= wrongAmount + 20 ether, "insufficient balance");

        bool setupReverted;
        try c.fallback{value: 10 ether}() {
            setupReverted = false;
        } catch {
            setupReverted = true;
        }

        bool sameTimestampReverted;
        try c.fallback{value: 10 ether}() {
            sameTimestampReverted = false;
        } catch {
            sameTimestampReverted = true;
        }

        bool wrongValueReverted;
        if (wrongAmount == 10 ether) {
            wrongValueReverted = sameTimestampReverted;
        } else {
            try c.fallback{value: wrongAmount}() {
                wrongValueReverted = false;
            } catch {
                wrongValueReverted = true;
            }
        }

        assert(setupReverted == false && (wrongAmount == 10 ether ? wrongValueReverted : wrongValueReverted));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 wrongAmount) public payable {
        require(address(this).balance >= wrongAmount + 40 ether, "insufficient balance");

        // First successful setup call: fresh contract, so timestamp is greater than pastBlockTime (0).
        bool setupReverted;
        try c.call{value: 10 ether}("") {
            setupReverted = false;
        } catch {
            setupReverted = true;
        }

        // Capture the timestamp recorded by the setup call.
        uint256 recorded = c.pastBlockTime();

        // Second call: same block, so block.timestamp == pastBlockTime, must revert regardless of value.
        bool sameTimestampReverted;
        try c.call{value: 10 ether}("") {
            sameTimestampReverted = false;
        } catch {
            sameTimestampReverted = true;
        }

        // Call with the user-supplied value, still at the same timestamp: must revert.
        bool wrongValueReverted;
        if (wrongAmount == 10 ether) {
            wrongValueReverted = sameTimestampReverted;
        } else {
            try c.call{value: wrongAmount}("") {
                wrongValueReverted = false;
            } catch {
                wrongValueReverted = true;
            }
        }

        // A call reverts iff the timestamp condition fails (same block) or the value is wrong.
        // Here the timestamp condition necessarily fails, so every call must revert.
        assert(setupReverted == false &&
               sameTimestampReverted &&
               wrongValueReverted);
    }

    receive() external payable {}
}

