contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, uint ts) public payable {
        require(address(this).balance >= amount);

        // First call to set the baseline timestamp (or revert if amount != 10 ether).
        bool setupOk;
        try c.call{value: amount}("") { setupOk = true; } catch { setupOk = false; }
        uint recordedBefore = c.pastBlockTime();

        // Second call: same value, and we cannot control block.timestamp, so the predicate is
        // over the observed post-state and the parameters.
        bool reverted;
        try c.call{value: amount}("") { reverted = false; } catch { reverted = true; }

        // General rule: if the amount is not exactly 10 ether, the call must revert and not change
        // pastBlockTime. If the amount is exactly 10 ether and the first call succeeded, the second
        // call must either revert (timestamp not greater than recorded) or succeed, but it can never
        // succeed while leaving pastBlockTime unchanged (a successful call always updates it).
        assert(
            (amount != 10 ether && reverted && c.pastBlockTime() == recordedBefore) ||
            (amount == 10 ether && setupOk && (!reverted ? c.pastBlockTime() > recordedBefore : true)) ||
            (amount == 10 ether && !setupOk && reverted && c.pastBlockTime() == recordedBefore)
        );
    }

    receive() external payable {}
}

