    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        require(address(this).balance >= 10 ether);

        uint256 before = c.pastBlockTime();
        bool ok = true;
        try c.fallback{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        if (block.timestamp > before) {
            assert(ok);
            assert(c.pastBlockTime() == block.timestamp);
        } else {
            assert(!ok);
            assert(c.pastBlockTime() == before);
        }
    }

    receive() external payable {}
}

