contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    uint public pastBlockTime;

    function run(uint amount, uint waitTime) public payable {
        require(address(this).balance >= amount, "not enough balance");

        uint ts = block.timestamp + (waitTime % 1000);

        (bool ok, ) = address(c).call{value: amount}(abi.encodeWithSignature(""));
        bool reverted = !ok;

        if (amount != 10 ether) {
            assert(reverted);
            return;
        }

        assert(!reverted);

        uint past = c.pastBlockTime();
        assert(past == ts || past >= block.timestamp);

        if (block.number % 15 == 0) {
            assert(address(c).balance == 0);
        } else {
            assert(address(c).balance == amount);
        }
    }

    receive() external payable {}
}

