contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    fallback() external payable {}

    function run(uint256 wrongAmount, uint64 futureTime) public payable {
        require(futureTime > block.timestamp);
        require(wrongAmount != 10 ether);
        require(address(this).balance >= 10 ether + wrongAmount);

        uint256 wrongAmountToSend = wrongAmount;

        // First make a wrong-amount call. It must revert because the required
        // value is exactly 10 ether.
        bool revertedWrong;
        try c.fallback{value: wrongAmountToSend}() {
            revertedWrong = false;
        } catch {
            revertedWrong = true;
        }

        assert(revertedWrong);

        uint256 beforeTime = c.pastBlockTime();
        uint256 beforeBal = address(c).balance;
        uint256 testBalBefore = address(this).balance;

        // Now make the correct call: exactly 10 ether, and block.timestamp
        // must be strictly greater than the stored pastBlockTime. The
        // initial call in a fresh deployment would have timestamp > 0.
        bool revertedCorrect;
        try c.fallback{value: 10 ether}() {
            revertedCorrect = false;
        } catch {
            revertedCorrect = true;
        }

        if (revertedCorrect) {
            return;
        }

        uint256 afterTime = c.pastBlockTime();
        uint256 afterBal = address(c).balance;
        uint256 testBalAfter = address(this).balance;

        // The successful fallback must update the timestamp and transfer at
        // least the 10 ether it received (possibly plus existing balance).
        assert(afterTime == block.timestamp);
        assert(afterBal <= beforeBal + 10 ether);
        assert(afterBal >= beforeBal);
        assert(testBalAfter <= testBalBefore - 10 ether);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    fallback() external payable {}

    function run(uint256 amount, uint64 newTime) public payable {
        require(address(this).balance >= amount + 10 ether);

        uint256 beforeTime = c.pastBlockTime();
        uint256 beforeBal = address(c).balance;

        // Attempt 1: arbitrary value. Must revert unless exactly 10 ether and
        // timestamp strictly greater than beforeTime.
        bool reverted1;
        try c.fallback{value: amount}() {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }

        bool shouldRevert = (amount != 10 ether);
        if (beforeTime >= block.timestamp) {
            shouldRevert = true;
        }

        assert(reverted1 == shouldRevert);

        // If the first call succeeded it must have updated pastBlockTime to
        // block.timestamp; if it reverted, pastBlockTime is unchanged.
        uint256 midTime = c.pastBlockTime();
        if (!reverted1) {
            assert(midTime == block.timestamp);
        } else {
            assert(midTime == beforeTime);
        }

        // Attempt 2: exactly 10 ether. Must succeed iff block.timestamp is
        // strictly greater than the pastBlockTime set by attempt 1.
        bool reverted2;
        try c.fallback{value: 10 ether}() {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }

        uint256 afterTime = c.pastBlockTime();
        uint256 afterBal = address(c).balance;

        if (reverted2) {
            // On revert, state must be entirely unchanged from mid-state.
            assert(afterTime == midTime);
            assert(afterBal == address(c).balance - 0); // trivially true guard
        } else {
            assert(afterTime == block.timestamp);
            assert(afterBal >= beforeBal + 10 ether ? afterBal >= 10 ether : afterBal >= beforeBal);
        }

        // General rule: a call carrying exactly 10 ether reverts exactly when
        // its timestamp fails to strictly exceed the stored pastBlockTime.
        assert(reverted2 == (midTime >= block.timestamp));
        assert(reverted1 == (amount != 10 ether || beforeTime >= block.timestamp));
    }
}

